            return;
        }
        DB::transaction(function () {
            $images = [];
            foreach (['hero' => 'hero/packaging-1600.webp', 'materials' => 'gallery/materials.webp', 'pouches' => 'products/pouches.webp', 'spout' => 'products/spout.webp', 'labels' => 'products/labels.webp', 'rolls' => 'products/rolls.webp', 'application' => 'gallery/application.webp'] as $key => $source) {
                $file = public_path('images/'.$source);
                $size = getimagesize($file);
                $path = 'cms-media/starter-'.$key.'.webp';
                if (! Storage::disk('local')->exists($path)) {
                    Storage::disk('local')->put($path, file_get_contents($file));
                }$images[$key] = Media::firstOrCreate(['path' => $path], ['uuid' => (string) Str::uuid(), 'original_name' => basename($file), 'mime' => 'image/webp', 'size' => filesize($file), 'width' => $size[0], 'height' => $size[1], 'alt' => match ($key) {
                    'hero' => 'Illustrative charcoal, orange and ivory pouch concepts with a blank label roll','materials' => 'Illustrative blank label rolls and packaging material swatches','pouches' => 'Illustrative unbranded stand-up packaging pouches','spout' => 'Illustrative ivory flexible spout pouch','labels' => 'Illustrative blank product label rolls','rolls' => 'Illustrative printed packaging roll concepts',default => 'Illustrative packaging application and material details'
                }, 'caption' => 'Original illustrative concept; not a photograph of company facilities or a confirmed product offering.']);
            }
            $pages = [
                'home' => ['Protect the product. Elevate the impression.', 'A considered starting point for packaging, printing, and your next product idea.', '<h2>More than a package. A part of your product.</h2><p>Amalez Pack Trade works in packaging and printing solutions. Start with your product, its journey, and the impression you want to make. Explore format guides, materials, and printing considerations before discussing your requirement.</p>', 'home', 'hero'],
                'about' => ['A considered approach to packaging.', 'Amalez Pack Trade · Packaging and Printing Solutions.', '<h2>Start with understanding.</h2><p>A pack has a practical job to do. It also has a story to tell. Our website brings together packaging and printing topics that can help shape a clearer product brief.</p><h2>Keep the conversation clear.</h2><p>Materials, specifications, artwork, and supply requirements should be confirmed for each project. We prefer clear requirements to unverified promises.</p><p>Company history, registered business details, and other corporate information will be added after confirmation.</p>', 'standard', 'materials'],
                'services' => ['Different products. Different possibilities.', 'Explore packaging formats, labels, printing, and the details that shape a useful brief.', '<p>The following service concepts are illustrative. Final scope, availability, materials, and suitability must be confirmed for your product before quotation.</p>', 'standard', null],
                'blog' => ['Ideas worth unpacking.', 'Original guides to packaging decisions, clearer artwork, and better product briefs.', '<p>General editorial guidance for discussion. These articles do not claim company certifications or specific production capabilities.</p>', 'standard', null],
                'contact' => ['Your next packaging conversation.', 'Tell us about the product, the format, and the details that matter.', '<p>Use the inquiry form to share a packaging or printing requirement. Your submission is stored securely for review by authorized administrators. Verified contact information will appear here when provided.</p>', 'contact', null],
                'faq' => ['Clear answers. Better beginnings.', 'Practical questions to help you prepare a packaging and printing brief.', '<p>These answers are general guidance. Product-specific suitability and commercial details need confirmation.</p>', 'faq', null],
                'infrastructure' => ['Infrastructure information.', 'Verified information will be added when available.', '<p>Facility, equipment, production, and manufacturing details have not been confirmed for publication. No such capabilities are advertised on this website. This page is reserved for approved information.</p>', 'standard', null],
                'privacy-policy' => ['Privacy policy.', 'Provisional policy text for review before broader business use.', '<p><strong>Draft for review:</strong> The business must confirm its legal identity, privacy contact, retention policy, and applicable legal requirements.</p><h2>Information submitted through this website</h2><p>Contact forms collect the fields shown to you, your inquiry, and a record of consent. Details are stored in the website database and are accessible to authorized owners and managers for reviewing and responding to inquiries. They are not displayed publicly.</p><h2>Comments and cookies</h2><p>If comments are enabled, approved commenter names and messages appear publicly; email addresses remain private. Essential cookies support secure forms and administrator sign-in. Optional analytics is loaded only after consent when configured.</p><h2>Requests and updates</h2><p>Use the contact page to raise a privacy request. Verified business contact details and a finalized policy will be published after review.</p>', 'legal', null],
                'terms-and-conditions' => ['Terms and conditions.', 'Provisional website terms requiring business and legal review.', '<p><strong>Draft for review:</strong> These terms must be finalized by the business before commercial reliance.</p><h2>Website information</h2><p>Illustrative packaging formats and editorial guidance are provided for discussion. They do not confirm availability, suitability, certifications, machinery ownership, or a binding quotation.</p><h2>Project requirements</h2><p>Materials, specifications, artwork, quantities, pricing, delivery, and other commercial requirements need separate written confirmation. An inquiry submission is not an order acceptance.</p><h2>Responsible use</h2><p>Do not submit unlawful, misleading, or harmful content, attempt unauthorized access, or misuse the forms. Contact the business through the contact page to discuss your requirement.</p>', 'legal', null],
                'cookie-policy' => ['Cookie policy.', 'Your choices, clearly explained.', '<h2>Essential cookies</h2><p>The website uses session and CSRF cookies to support secure forms and administrator authentication. These functions help protect submitted information.</p><h2>Optional analytics</h2><p>If an authorized owner configures Google Analytics, its script is loaded only after you allow optional analytics. Choose Essential only to avoid loading it. Your choice is stored in local browser storage.</p><h2>Changing your choice</h2><p>Open Cookie preferences in the footer. Withdrawing consent disables future analytics tracking in this page; browser settings can be used to remove cookies already stored. Additional policy details remain subject to business review.</p>', 'legal', null],
            ];
            foreach ($pages as $slug => [$title,$excerpt,$body,$template,$image]) {
                $page = Page::firstOrCreate(['slug' => $slug], ['title' => $title, 'excerpt' => $excerpt, 'body' => $body, 'template' => $template, 'status' => 'published', 'published_at' => now(), 'featured_media_id' => $image ? $images[$image]->id : null]);
                $page->seo()->firstOrCreate([], ['data' => ['title' => ($slug === 'home' ? 'Packaging & Printing Solutions' : $title).' | Amalez Pack Trade', 'description' => $excerpt, 'index' => false, 'schema_mode' => 'auto']]);
            }
            $home = Page::whereSlug('home')->firstOrFail();
            $this->section($home, 'image', 'The details make the difference.', '<p>Define the product, its journey, and the details that matter before choosing a format. Consider materials, structure, print, and handling together rather than as isolated decisions.</p>', $images['materials']->id, 0);
            $this->section($home, 'services', 'The right format starts with the right questions.', '<p>Explore illustrative packaging and printing service concepts. Every specification should be confirmed for the actual product.</p>', null, 1);
            $this->section($home, 'text', 'Your product. Your priorities. A considered brief.', '<h3>Find the format</h3><p>Start with the product, fill method, portion, and route to market.</p><h3>Consider the material</h3><p>Discuss barrier, handling, storage, and compatibility requirements.</p><h3>Define the impression</h3><p>Bring dimensions, artwork, label content, and finishing questions together.</p><h3>Confirm the details</h3><p>Review specifications and commercial requirements before proceeding.</p>', null, 2);
            $this->section($home, 'posts', 'A little more clarity, in every article.', '<p>Practical thinking for your next packaging conversation.</p>', null, 3);
            $this->section($home, 'cta', "Let's create a clearer packaging brief.", '<p>Share your product requirements and the questions you need to answer.</p>', null, 4);
            $faq = Page::whereSlug('faq')->firstOrFail();
            foreach (['What should I include in a packaging inquiry?' => 'Include your product, approximate fill weight or volume, format, dimensions, quantity, storage conditions, filling method, and artwork requirements.', 'Are these confirmed products and capabilities?' => 'The initial service guides and imagery are illustrative. Availability and final specifications require confirmation. No manufacturing or certification claims are made.', 'Can I discuss custom sizes and print requirements?' => 'Use the contact form to describe the requirement. Materials, dimensions, artwork, quantities, and suitability can then be reviewed as part of the project discussion.', 'Has my form been submitted successfully?' => 'A successful inquiry displays a unique reference after it is stored. This is separate from optional email notification delivery.'] as $q => $a) {
                $this->section($faq, 'faq', $q, '<p>'.$a.'</p>', null, $faq->sections()->count());
            }
            $services = [['flexible-packaging', 'Flexible Packaging', null, 'pouches', 'Flexible formats considered around protection, handling, and presentation.'], ['stand-up-pouches', 'Stand-Up Pouches', 'flexible-packaging', 'pouches', 'Freestanding formats with space for a distinctive shelf presence.'], ['zipper-pouches', 'Stand-Up Zipper Pouches', 'stand-up-pouches', 'pouches', 'Resealable pouch concepts for projects where repeated access matters.'], ['spout-pouches', 'Spout Pouches', 'flexible-packaging', 'spout', 'Flexible formats centered on controlled pouring and convenient handling.'], ['labels-and-printing', 'Labels and Printing', null, 'labels', 'The finishing detail that connects a pack to its product identity.'], ['printed-rolls', 'Printed Rolls', null, 'rolls', 'Continuous packaging material considered around the filling process.'], ['packaging-solutions', 'Packaging Solutions', null, 'application', 'A structured starting point for custom packaging and print requirements.']];
            foreach ($services as $sort => [$slug,$title,$parent,$image,$excerpt]) {
                $s = Service::firstOrCreate(['slug' => $slug], ['title' => $title, 'parent_id' => $parent ? Service::whereSlug($parent)->value('id') : null, 'excerpt' => $excerpt, 'body' => '<h2>Define the requirement.</h2><p>'.$excerpt.' Start by describing the product, how it is filled, the storage environment, and how the package will be used.</p><h3>Details to discuss</h3><ul><li>Dimensions, fill quantity, and structural preferences.</li><li>Material compatibility, protection, and handling requirements.</li><li>Artwork, label content, closures, and print presentation.</li><li>Approximate quantities and the commercial brief.</li></ul><p>This is an illustrative service guide. Final availability, materials, suitability, and specifications require confirmation.</p>', 'status' => 'published', 'published_at' => now(), 'featured_media_id' => $images[$image]->id, 'featured' => ! $parent, 'confirmed' => false, 'sort_order' => $sort]);
                $s->seo()->firstOrCreate([], ['data' => ['title' => $title.' | Amalez Pack Trade', 'description' => $excerpt, 'schema_mode' => 'auto', 'index' => false]]);
                $s->gallery()->firstOrCreate(['media_id' => $images[$image]->id], ['caption' => 'Illustrative '.$title.' concept', 'sort_order' => 0]);
                $this->section($s, 'faq', 'What information helps define this format?', '<p>Describe the product, dimensions, filling process, protection requirements, artwork, and approximate quantity. Final specifications must be reviewed for the actual application.</p>', null, 0);
            }
            $category = Category::firstOrCreate(['slug' => 'packaging-guides'], ['name' => 'Packaging guides']);
            $tag = Tag::firstOrCreate(['slug' => 'project-planning'], ['name' => 'Project planning']);
            foreach ($this->articles() as $index => [$slug,$title,$excerpt,$image,$body]) {
                $post = Post::firstOrCreate(['slug' => $slug], ['title' => $title, 'excerpt' => $excerpt, 'body' => $body, 'featured_media_id' => $images[$image]->id, 'status' => 'published', 'published_at' => now()->subDays(3 - $index), 'author_name' => 'PackTrade Editorial', 'comments_enabled' => true]);
                $post->categories()->syncWithoutDetaching([$category->id]);
                $post->tags()->syncWithoutDetaching([$tag->id]);
                $post->seo()->firstOrCreate([], ['data' => ['title' => $title.' | Amalez Pack Trade', 'description' => $excerpt, 'schema_mode' => 'auto', 'index' => false]]);
            }
            foreach (['header' => ['Home' => '/', 'About' => '/about', 'Services' => '/services', 'Blog' => '/blog', 'Contact' => '/contact'], 'footer' => ['About Us' => '/about', 'Services' => '/services', 'Journal' => '/blog', 'FAQ' => '/faq', 'Infrastructure' => '/infrastructure', 'Privacy Policy' => '/privacy-policy', 'Terms and Conditions' => '/terms-and-conditions', 'Cookie Policy' => '/cookie-policy']] as $location => $links) {
                $menu = NavigationMenu::firstOrCreate(['location' => $location], ['name' => ucfirst($location).' navigation']);
                foreach ($links as $label => $url) {
                    $menu->items()->firstOrCreate(['url' => $url], ['label' => $label, 'sort_order' => $menu->items()->count(), 'enabled' => true]);
                }
            }
            foreach ([['name', 'Full name', 'text', true], ['email', 'Email address', 'email', true], ['phone', 'Phone number', 'tel', false], ['company', 'Company name', 'text', false], ['service', 'Service interested in', 'service', false], ['subject', 'Subject', 'text', false], ['message', 'Requirement details', 'textarea', true]] as $order => [$key,$label,$type,$required]) {
                FormField::firstOrCreate(['key' => $key], compact('label', 'type', 'required') + ['sort_order' => $order, 'enabled' => true]);
            }
            foreach (['branding' => ['tagline' => 'Packaging & Printing Solutions', 'hero_kicker' => 'THE POSSIBILITIES ARE IN THE PACKAGING', 'hero_footnote' => 'FLEXIBLE FORMATS / LABELS & PRINT / YOUR NEXT BRIEF', 'footer_description' => 'Packaging and printing solutions. Considered around your product.', 'contact_heading' => 'Tell us what you are packing.', 'contact_intro' => 'Share the essentials. Your inquiry is stored securely for the authorized team to review.'], 'business' => ['legal_name' => '', 'email' => '', 'telephone' => '', 'address' => '', 'verified' => false, 'local_business_verified' => false], 'social_links' => [], 'indexable' => false, 'notification_email' => '', 'analytics_id' => '', 'analytics_position' => 'header', 'cms_seed_version' => 1] as $key => $value) {
                WebsiteSetting::firstOrCreate(['key' => $key], ['value' => $value]);
            }
        });
        Cms::forget();
